  ["Hear this place"] = "Diesen Ort hören",
  ["Hover an item in your bags: Bastian's adds its price line."] = "Fahr mit der Maus über einen Gegenstand in deinen Taschen: Bastian's zeigt seine Preiszeile.", -- luacheck: ignore 631
  ["Hover an item in your bags: its price line."] = "Maus über einen Gegenstand in deinen Taschen: seine Preiszeile.", -- luacheck: ignore 631
  ["Know what it is worth"] = "Wissen, was es wert ist",
  ["Look"] = "Aussehen",
  ["Look something up"] = "Etwas nachschlagen",
  ["Needs %s."] = "Braucht %s.",
  ["One key clears the screen for the view"] = "Eine Taste räumt den Bildschirm für die Aussicht frei",
  ["One key hides the interface but the action bars."] = "Eine Taste blendet die Oberfläche bis auf die Aktionsleisten aus.", -- luacheck: ignore 631
  ["Or switch everything on"] = "Oder alles einschalten",
  ["Pins on the minimap"] = "Markierungen auf der Minikarte",
  ["Prices, and who of your characters has what"] = "Preise, und welcher deiner Charaktere was hat",
  ["Quest givers' words around the Orbiter, your answers as symbols."] = "Die Worte der Questgeber rund um den Orbiter, deine Antworten als Symbole.", -- luacheck: ignore 631
  ["Rings of your emotes, lines and macros on one key; a thank-you when someone buffs or resurrects you; a bow or a polite no to a duel or a trade."] = "Ringe deiner Emotes, Zeilen und Makros auf einer Taste; ein Dank, wenn dich jemand bufft oder wiederbelebt; eine Verbeugung oder ein höfliches Nein zu einem Duell oder Handel.", -- luacheck: ignore 631
  ["Roleplay with Bastian's"] = "Rollenspiel mit Bastian's",
  ["Route steps"] = "Routenschritte",
  ["Route there on anything: road, flight, boat."] = "Eine Route zu allem: Straße, Flug, Schiff.",
  ["Show the welcome at every login"] = "Das Willkommen bei jedem Login zeigen",
  ["Sit by a fire together, share it with your group, a camp ring for the evening."] = "Gemeinsam am Feuer sitzen, es mit der Gruppe teilen, ein Lagerring für den Abend.", -- luacheck: ignore 631
  ["Switch on %s on the Suite page."] = "Schalte %s auf der Suite-Seite ein.",
  ["Talk to a quest giver with the conversation on"] = "Mit einem Questgeber sprechen, das Gespräch eingeschaltet", -- luacheck: ignore 631
  ["Talk to people without quest windows"] = "Mit Leuten reden ohne Questfenster",
  ["Text"] = "Text",
  ["The Gestures ring"] = "Der Gesten-Ring",
  ["The Orbiter"] = "Der Orbiter",
  ["The Orbiter plays Spoken's voices for quests, places, books and bosses, and the game's voice where Spoken has none."] = "Der Orbiter spielt Spokens Stimmen für Quests, Orte, Bücher und Bosse und die Stimme des Spiels, wo Spoken keine hat.", -- luacheck: ignore 631
  ["The Orbiter plays the zone's story."] = "Der Orbiter spielt die Geschichte der Zone.",
  ["The campfire"] = "Das Lagerfeuer",
  ["The hub: every app's settings, the Suite page, Help."] = "Der Hub: die Einstellungen jeder App, die Suite-Seite, Hilfe.", -- luacheck: ignore 631
  ["The land speaks"] = "Das Land spricht",
  ["The land tells its stories as you walk (the Orbiter with Spoken)"] = "Das Land erzählt seine Geschichten, während du gehst (der Orbiter mit Spoken)", -- luacheck: ignore 631
  ["The screen for the view"] = "Der Bildschirm für die Aussicht",
  ["The search opens a page for anything."] = "Die Suche öffnet eine Seite für alles.",
  ["The suite's button at the minimap"] = "Der Knopf der Suite an der Minikarte",
  ["The suite's words"] = "Die Worte der Suite",
  ["The way there, by road, flight and boat"] = "Der Weg dorthin, über Straße, Flug und Schiff",
  ["The welcome stays away at login; the General page brings it back."] = "Das Willkommen bleibt beim Login weg; die Allgemein-Seite holt es zurück.", -- luacheck: ignore 631
  ["The welcome window at every login, until Don't show again in its corner (plan-launch-version D)."] = "Das Willkommensfenster bei jedem Login, bis Nicht mehr zeigen in seiner Ecke (plan-launch-version D).", -- luacheck: ignore 631
  ["Try it"] = "Ausprobieren",
  ["What matters for this way"] = "Was für diesen Weg zählt",
  ["What you get"] = "Was du bekommst",
  ["Where things are"] = "Wo die Dinge sind",
  ["You know the way."] = "Du kennst den Weg.",
  ["Your first five minutes"] = "Deine ersten fünf Minuten",
  ["Your gestures on a ring, thanks in your own words"] = "Deine Gesten auf einem Ring, Dank in deinen eigenen Worten", -- luacheck: ignore 631
  ["Your pack"] = "Dein Gepäck",
  -- the welcome's information layer (02.11.2026)
  ["Highpeak"] = "Hochgipfel",
  ["Greenback Ridge"] = "Grünrücken",
  ["Peacebloom"] = "Friedensblume",
  ["%d yd high, %d yd away"] = "%d Meter hoch, %d Meter entfernt",
  ["%d yd away"] = "%d Meter entfernt",
  -- the artist's credit under a hand-drawn dungeon map (ADR 0048, 02.11.2026)
  ["Map by %s"] = "Karte von %s",
  ["Map by %s (%s), used with kind permission. Thank you!"] = "Karte von %s (%s), mit freundlicher Genehmigung. Danke!",
  ["Click, then Ctrl+C to copy the address"] = "Klicken, dann mit Strg+C die Adresse kopieren",
  -- the minimap buttons
  ["Welcome"] = "Willkommen",
  ["Its own minimap button for the welcome"] = "Eigener Minimap-Button für die Begrüßung",
  ["A button at the minimap that shows the welcome with the Wanderer and the Scholar again."] = "Ein Button an der Minimap, der die Begrüßung mit dem Wanderer und dem Gelehrten wieder zeigt.",
  ["%s is switched off. Its page has the switch to turn it on."] = "%s ist ausgeschaltet. Auf seiner Seite schaltest du es ein.",
  ["Click: its page, to switch it on."] = "Klick: seine Seite, zum Einschalten.",

  -- What's new (ADR 0021, LG5): the release notes, keyed by their English text
  ['Quests show the zone where you pick them up, and "from" on a collect objective only names a creature that really has the item.'] = 'Quests zeigen die Zone, in der du sie annimmst, und "von" bei einem Sammelziel nennt nur noch eine Kreatur, die den Gegenstand wirklich hat.',
  ["Quest givers and hand-ins that ForeverDB players saw in the game fill gaps on the map sooner."] = "Questgeber und Abgabeorte, die ForeverDB-Spieler im Spiel gesehen haben, füllen Lücken auf der Karte schneller.",
  ["A rumour in the gold book names its three newest travellers and counts the others."] = "Ein Gerücht im Goldbuch nennt seine drei neuesten Reisenden und zählt die übrigen.",
  ["A quest whose next step has no known place no longer routes you back to its giver."] = "Eine Quest, deren nächster Schritt keinen bekannten Ort hat, führt dich nicht mehr zurück zu ihrem Questgeber.",
  ['A quest whose place nobody knows says so, with Map and Route greyed; the quest round stops once per open objective, and "Route to" picks among the nearest places.'] = 'Eine Quest, deren Ort niemand kennt, sagt das, mit ausgegrauter Karte und Route; die Questrunde hält einmal pro offenem Ziel, und "Route zu" wählt unter den nächsten Orten.',
  ["Quests that ask for an item no loot table knew, like Mirror Lake's water sample, now lead to where the item is found."] = "Quests, die einen Gegenstand verlangen, den keine Beutetabelle kannte, wie die Wasserprobe vom Spiegelsee, führen jetzt dorthin, wo der Gegenstand zu finden ist.",
  ['The suite notes where your quest steps counted, and "Copy my captures" can share those places, so quests no source can place get one later.'] = 'Die Suite merkt sich, wo deine Questschritte gezählt haben, und "Meine Aufzeichnungen kopieren" kann diese Orte teilen, damit Quests, die keine Quelle verorten kann, später einen Ort bekommen.',
  ["The flight bar and the learned flight times name the flight you took; the game lists its flight points in another order than its buttons."] = "Die Flugleiste und die gelernten Flugzeiten nennen den Flug, den du genommen hast; das Spiel führt seine Flugpunkte in einer anderen Reihenfolge als seine Schaltflächen.",
  ["Abandoning a quest that takes items back no longer raises an error; the game's question names the items."] = "Das Abbrechen einer Quest, die Gegenstände zurücknimmt, löst keinen Fehler mehr aus; die Frage des Spiels nennt die Gegenstände.",
  ["A reload or a logout at the mailbox no longer raises an error in Alts."] = "Ein Neuladen oder Ausloggen am Briefkasten löst in Twinks keinen Fehler mehr aus.",
  ["Ring wedges and the Campfire's foot icon act on a click whatever the game's key-down setting, and a ring opened by its toggle key stays until that key closes it, over a reload too."] = "Ringsegmente und das Fußsymbol des Lagerfeuers reagieren auf einen Klick, egal wie die Tastendruck-Einstellung des Spiels steht, und ein mit seiner Umschalttaste geöffneter Ring bleibt, bis diese Taste ihn schließt, auch über ein Neuladen hinweg.",
  ["Courtesy whispers its line to the person who buffed or invited you when the game gives their whole name, and offers its ring for a buff that landed during a longer fight."] = "Höflichkeit flüstert ihre Zeile der Person zu, die dich gebufft oder eingeladen hat, wenn das Spiel deren ganzen Namen nennt, und bietet ihren Ring für einen Buff an, der während eines längeren Kampfes kam.",
  ["Gold's ledger now books your auction house sales and purchases when you open the mailbox; it raised an error instead."] = "Das Kassenbuch von Gold verbucht jetzt deine Verkäufe und Käufe im Auktionshaus, wenn du den Briefkasten öffnest; stattdessen kam bisher ein Fehler.",
  ["The flight bar goes away when you land, and Route now learns how long your flights take; on WoW Forever it never noticed a landing."] = "Die Flugleiste verschwindet, wenn du landest, und Route lernt jetzt, wie lange deine Flüge dauern; in WoW Forever hat es eine Landung nie bemerkt.",
  ["The map no longer sends you to quest givers who are not there or have nothing to give: world event quests wait for their event, quests that are not in the game are gone, and a giver who does not list a quest loses its pin until you gain a level."] = "Die Karte schickt dich nicht mehr zu Questgebern, die nicht da sind oder nichts zu vergeben haben: Weltereignis-Quests warten auf ihr Ereignis, Quests, die es im Spiel nicht gibt, sind weg, und ein Geber, der eine Quest nicht auflistet, verliert seine Markierung, bis du eine Stufe aufsteigst.",
  ['Quests far below your level stay on the map in grey, marked "Low level".'] = 'Quests weit unter deiner Stufe bleiben in Grau auf der Karte, markiert mit "Niedrige Stufe".',
  ["The gold stories' map scales smoothly with its window, which takes the map's shape; tokens light up under the cursor; the book opens on the map."] = "Die Karte der Goldgeschichten skaliert sanft mit ihrem Fenster, das die Form der Karte annimmt; Marker leuchten unter dem Mauszeiger auf; das Buch öffnet sich auf der Karte.",
  ["Zone level ranges on the map are coloured for your character's level."] = "Die Stufenbereiche der Zonen auf der Karte sind passend zur Stufe deines Charakters eingefärbt.",
  ['A dungeon in a list says "in 4 levels" while it is still ahead of you.'] = 'Ein Dungeon in einer Liste sagt "in 4 Stufen", solange er noch vor dir liegt.',
  ["A zone's page says the fishing skill it asks for."] = "Die Seite einer Zone nennt die Angelfertigkeit, die sie verlangt.",
  ["The map's footer shows the travel time to the point under your cursor."] = "Die Fußzeile der Karte zeigt die Reisezeit zum Punkt unter deinem Mauszeiger.",
  ["Items whose cheapest listing is far under their 30-day median are marked as a bargain."] = "Gegenstände, deren günstigstes Angebot weit unter ihrem 30-Tage-Median liegt, sind als Schnäppchen markiert.",
  ["A small bar shows the time left on a flight whose duration you flew before."] = "Eine kleine Leiste zeigt die verbleibende Zeit eines Flugs, dessen Dauer du schon einmal geflogen bist.",
  ["Dungeon pages list the quests whose targets live inside, from the Classic data, for 16 more dungeons and raids."] = "Dungeon-Seiten listen die Quests auf, deren Ziele darin leben, aus den Classic-Daten, jetzt für 16 weitere Dungeons und Schlachtzüge.",
  ['A "Class quests" view lists your class\'s quests by status and level.'] = 'Eine Ansicht "Klassenquests" listet die Quests deiner Klasse nach Status und Stufe.',
  ["Targeting or mousing over a rare creature shows its name with a Map button."] = "Wenn du eine seltene Kreatur anvisierst oder mit der Maus darüberfährst, erscheint ihr Name mit einem Karten-Button.",
  ["A route says in one word whether the way is safe, needs care or is risky for your level."] = "Eine Route sagt in einem Wort, ob der Weg sicher ist, Vorsicht verlangt oder für deine Stufe riskant ist.",
  ['"Craft for gold" lists the recipes you know by profit, with the best way to sell each product.'] = '"Für Gold herstellen" listet die Rezepte, die du kennst, nach Gewinn, mit dem besten Verkaufsweg für jedes Produkt.',
  ['A "Trainer" view lists the spells your class trainers teach you now, with cost and the nearest trainer.'] = 'Eine Ansicht "Lehrer" listet die Zauber, die dir deine Klassenlehrer jetzt beibringen, mit Kosten und dem nächsten Lehrer.',
  ["Your character's page names the gold to save for: the next training, riding and a mount."] = "Die Seite deines Charakters nennt das Gold, auf das du sparen solltest: das nächste Training, Reiten und ein Reittier.",
  ["A dungeon's page lists your characters' runs and lockouts."] = "Die Seite eines Dungeons listet die Durchläufe und Instanzbindungen deiner Charaktere.",
  ["A farm spot's page shows your own gold per hour there after twenty kills, beside the guide's figure."] = "Die Seite eines Farmplatzes zeigt nach zwanzig Kills dein eigenes Gold pro Stunde dort, neben dem Wert des Guides.",
  ["The Atlas has a rail of seven sections with tabs instead of a bar of nineteen buttons."] = "Der Atlas hat eine Leiste mit sieben Bereichen und Tabs statt einer Reihe von neunzehn Buttons.",
  ["The Atlas's search stands in the title bar, always at hand."] = "Die Suche des Atlas steht in der Titelleiste, immer griffbereit.",
  ["The Atlas's lists come in pages that fit the window instead of a scroll."] = "Die Listen des Atlas kommen in Seiten, die ins Fenster passen, statt in einer Bildlaufleiste.",
  ["Stat tiles on Here, Gold and Characters; a dungeon's and a character's page read in tabs."] = "Kennzahlen-Kacheln auf Hier, Gold und Charaktere; die Seite eines Dungeons und eines Charakters liest sich in Tabs.",
  ["Gold's Bags tab gives one answer per bag item with the reason."] = "Der Taschen-Tab von Gold gibt für jeden Gegenstand in den Taschen eine Antwort mit Begründung.",
  ["The settings hub reads as a rail of apps with their one-line purpose and every option on a card."] = "Die Einstellungszentrale zeigt eine Leiste der Apps mit ihrem Zweck in einer Zeile und jede Option auf einer Karte.",
  ['Share the walks, flight times and ride waits your game learned through "Copy my captures" in the settings.'] = 'Teile die Wege, Flugzeiten und Fahrtwartezeiten, die dein Spiel gelernt hat, über "Meine Aufnahmen kopieren" in den Einstellungen.',
  ["Dragging a window no longer jumps it over the top of the screen, and Dock works again after the docked Browser was closed by hand."] = "Beim Ziehen springt ein Fenster nicht mehr über den oberen Bildschirmrand, und Andocken funktioniert wieder, nachdem der angedockte Browser von Hand geschlossen wurde.",
  ["In a narrow Browser window a click on a view's row now shows the page it opens."] = "In einem schmalen Browser-Fenster zeigt ein Klick auf die Zeile einer Ansicht jetzt die Seite, die sie öffnet.",
  ["The Browser's search always looks in every list; the list's own filter narrows the list."] = "Die Suche des Browsers durchsucht immer jede Liste; der eigene Filter der Liste grenzt die Liste ein.",
  ["The physical map no longer shows a stray strip of old parchment west of Kalimdor."] = "Die physische Karte zeigt westlich von Kalimdor keinen verirrten Streifen alten Pergaments mehr.",
  ["The level band under a zone's name on the map reads clearly in every difficulty colour."] = "Der Stufenbereich unter dem Namen einer Zone auf der Karte ist in jeder Schwierigkeitsfarbe gut lesbar.",
  ["A farm spot without a known gold rate says so once, and the text is no longer cut off."] = "Ein Farmplatz ohne bekannte Goldrate sagt das einmal, und der Text wird nicht mehr abgeschnitten.",
  ["A quest's sheet under the mouse on a chain's step shows over the Browser instead of behind it."] = "Das Blatt einer Quest unter der Maus auf dem Schritt einer Reihe erscheint über dem Browser statt dahinter.",
  ["The people on a quest's sheet show their faces again."] = "Die Personen auf dem Blatt einer Quest zeigen wieder ihre Gesichter.",
  ['The map\'s right-click menu no longer lists "Show on map" twice.'] = 'Das Rechtsklick-Menü der Karte listet "Auf Karte zeigen" nicht mehr doppelt.',
  ["A click on a class quest no longer empties the Class quests list while it is rebuilt."] = "Ein Klick auf eine Klassenquest leert die Liste Klassenquests nicht mehr, während sie neu aufgebaut wird.",
  ['A dungeon one level away now says "in 1 level".'] = 'Ein Dungeon, der eine Stufe entfernt ist, sagt jetzt "in 1 Stufe".',
  ["The gold book's text follows the suite's text size and uses three font sizes instead of seven."] = "Der Text des Goldbuchs folgt der Textgröße der Suite und nutzt drei Schriftgrößen statt sieben.",
  ["The gold book's maps and the story map's marks open their place on the world map."] = "Die Karten des Goldbuchs und die Markierungen der Geschichtenkarte öffnen ihren Ort auf der Weltkarte.",
  ["The names in the gold book's pages are links: hover for the tooltip, click to open."] = "Die Namen auf den Seiten des Goldbuchs sind Links: Mauszeiger darüber für den Tooltip, Klick zum Öffnen.",
  ["A page in the Browser has its own filter: type to narrow every list on it."] = "Eine Seite im Browser hat ihren eigenen Filter: Tippe, um jede Liste darauf einzugrenzen.",
  ["The Browser's sections and tabs are coloured symbols with text instead of green buttons."] = "Die Bereiche und Tabs des Browsers sind farbige Symbole mit Text statt grüner Buttons.",
  ["/balts opens your characters in the Browser: the list on the left, a character's tabs on the right."] = "/balts öffnet deine Charaktere im Browser: die Liste links, die Tabs eines Charakters rechts.",
  ["Gold's new Bargains tab lists the items selling far under their usual price."] = "Der neue Schnäppchen-Tab von Gold listet die Gegenstände, die weit unter ihrem üblichen Preis verkauft werden.",
  ["The Gold Stories list shows each story as a tile with Bastian's picture and its first words."] = "Die Liste der Goldgeschichten zeigt jede Geschichte als Kachel mit Bastians Bild und ihren ersten Worten.",
  ["The map keeps you centred by default; looking around pauses it until the map closes, and only the Centred button switches it off."] = "Die Karte hält dich standardmäßig zentriert; Umsehen pausiert das bis zum Schließen der Karte, und nur der Button Zentriert schaltet es ab.",
  ["The minimap shows only the herbs and ore the game's tracking really finds, not every known spawn."] = "Die Minikarte zeigt nur die Kräuter und Erze, die das Aufspüren des Spiels wirklich findet, nicht jeden bekannten Fundort.",
  ["A window you open always comes to the front, also one that was already open behind another."] = "Ein Fenster, das du öffnest, kommt immer nach vorn, auch eines, das schon hinter einem anderen offen war.",
  ["The campfire flame can be dragged anywhere and remembers its place."] = "Die Lagerfeuer-Flamme lässt sich überallhin ziehen und merkt sich ihren Platz.",
  ["Hovering a quest reward in the Orbiter shows the item's full stats."] = "Fährst du im Orbiter mit der Maus über eine Questbelohnung, zeigt er die vollständigen Werte des Gegenstands.",
  ["My quests lists every objective of a quest with its count, not just the first open one."] = "Meine Quests listet jedes Ziel einer Quest mit seinem Stand, nicht nur das erste offene.",
  ["A route starts on your side of a ridge instead of across a mountain."] = "Eine Route beginnt auf deiner Seite eines Bergrückens statt quer durch einen Berg.",
  ["After you die, Bastian's Route drops the old arrow and guides you on foot back to your corpse, marked clearly on the map."] = "Nach deinem Tod verwirft Bastian's Route den alten Pfeil und führt dich zu Fuß zurück zu deiner Leiche, die deutlich auf der Karte markiert ist.",
  ["/way now works without TomTom and starts a route; several lines become one route, and a button chooses a new route or adding to the current one."] = "/way funktioniert jetzt ohne TomTom und startet eine Route; mehrere Zeilen werden zu einer Route, und ein Button wählt zwischen einer neuen Route und dem Hinzufügen zur aktuellen.",
  ["The map shows only the quest targets you still need, each labelled with what to do there and how many are left."] = "Die Karte zeigt nur die Questziele, die du noch brauchst, jedes beschriftet mit dem, was dort zu tun ist, und wie viele noch fehlen.",
  ["The minimap follows your character even when the game reports no movement, on boats, after a knockback or a teleport."] = "Die Minikarte folgt deinem Charakter auch dann, wenn das Spiel keine Bewegung meldet: auf Booten, nach einem Rückstoß oder einer Teleportation.",
  ["Switching a layer off also clears its pins from the minimap."] = "Wenn du eine Ebene ausschaltest, verschwinden auch ihre Markierungen von der Minikarte.",
  ["Creatures found by hunter, druid, paladin and warlock tracking now show on Bastian's map styles."] = "Kreaturen, die durch das Aufspüren von Jäger, Druide, Paladin und Hexenmeister gefunden werden, erscheinen jetzt in Bastian's Kartenstilen.",
  ["Bastian's Courtesy is now an addon of its own: when someone helps you, a small ring offers a fitting thank-you, and your click says it in character."] = "Bastian's Courtesy ist jetzt ein eigenes Addon: Wenn dir jemand hilft, bietet ein kleiner Ring ein passendes Dankeschön an, und dein Klick spricht es in der Rolle deines Charakters aus.",
  ["The gesture ring stays open until you press its key again."] = "Der Gestenring bleibt offen, bis du seine Taste erneut drückst.",
  ["Routes inside Stormwind no longer detour around the harbour to reach a street nearby."] = "Routen innerhalb von Stormwind machen keinen Umweg mehr um den Hafen, um eine nahe Straße zu erreichen.",
  ["Trainers and vendors say what kind they are, also when their title has no word Trainer in it."] = "Lehrer und Händler sagen, was für welche sie sind, auch wenn ihr Titel das Wort Lehrer nicht enthält.",
  ["The campfire card is now a stylized flame you click: sit down, share or hide."] = "Die Lagerfeuer-Karte ist jetzt eine stilisierte Flamme zum Anklicken: hinsetzen, teilen oder ausblenden.",
  ["A new minimap button lights a kit you carry, and the foot icon offers what you can add to a fire, Violet Dust included."] = "Ein neuer Minikarten-Button entzündet ein Set, das du bei dir trägst, und das Fußsymbol bietet an, was du einem Feuer hinzufügen kannst, Violet Dust eingeschlossen.",
  ["Send to writes a character's name with its surname, so the mail reaches them on Forever."] = "Senden an schreibt den Namen eines Charakters mit seinem Nachnamen, damit die Post ihn auf Forever erreicht.",
  ["Alts can forget a character you deleted, and its filter now finds class, race, place and every item held."] = "Alts kann einen Charakter vergessen, den du gelöscht hast, und sein Filter findet jetzt Klasse, Volk, Ort und jeden gehaltenen Gegenstand.",
  ["A new key in Key Bindings opens whatever is under your mouse in the Browser."] = "Eine neue Taste in der Tastenbelegung öffnet im Browser, was sich unter deiner Maus befindet.",
  ["The quest window has a Route to the giver button."] = "Das Questfenster hat einen Button Route zum Geber.",
  ["A quest item you already hold no longer keeps its pin where it lay."] = "Ein Questgegenstand, den du schon besitzt, behält seine Markierung nicht mehr dort, wo er lag.",
  ["The chat's copy window has a scroll bar."] = "Das Kopierfenster des Chats hat eine Bildlaufleiste.",
  ["The chat input bar no longer disappears behind the window, and a reload no longer takes the keyboard."] = "Die Eingabeleiste des Chats verschwindet nicht mehr hinter dem Fenster, und ein Neuladen nimmt dir nicht mehr die Tastatur.",
  ["Quests now wait for the quest players were seen to need first, where that cannot lock them out."] = "Quests warten jetzt auf die Quest, die Spieler nachweislich zuerst brauchten, sofern sie dich dadurch nicht aussperren kann.",
  ['The Browser\'s search no longer stays on "Searching ..." while other things happen; a search that fails says so.'] = 'Die Suche des Browsers bleibt nicht mehr bei "Suche läuft ..." stehen, während anderes geschieht; eine Suche, die fehlschlägt, sagt es.',
  ["Bastian's Route now has the walk network of both continents: routes follow roads, passes and bridges instead of the straight line."] = "Bastian's Route hat jetzt das Wegenetz beider Kontinente: Routen folgen Straßen, Pässen und Brücken statt der geraden Linie.",
  ["The herbs and ore the game tracks no longer vanish from Bastian's minimap styles with a map layer, the pin limit or the layers-on-the-minimap setting; they show as yellow pins of their own."] = "Die Kräuter und Erze, die das Spiel aufspürt, verschwinden in Bastians Minikarten-Stilen nicht mehr wegen einer Kartenebene, des Pin-Limits oder der Einstellung für Ebenen auf der Minikarte; sie erscheinen als eigene gelbe Pins.",
  ["Gold finds the market prices on the live EU RP realm."] = "Gold findet die Marktpreise auf dem Live-EU-RP-Realm.",
  ["Herbs and ore on Bastian's minimap styles now sit exactly where the game's own dots are."] = "Kräuter und Erze in Bastians Minikarten-Stilen sitzen jetzt genau dort, wo die Punkte des Spiels selbst sind.",
  ["Hovering a quest lights its whole block in one colour and the row under the mouse in another, so chain quests no longer look like quests of their own."] = "Fährst du mit der Maus über eine Quest, leuchtet ihr ganzer Block in einer Farbe und die Zeile unter der Maus in einer anderen, sodass Questreihen nicht mehr wie eigenständige Quests aussehen.",
  ["Quests now say what to do first: the task sits right under the quest in My quests and opens the quest page, with the story last."] = "Quests sagen jetzt zuerst, was zu tun ist: Die Aufgabe steht direkt unter der Quest in Meine Quests und öffnet die Questseite, die Geschichte kommt zuletzt.",
  ['Objectives show their count once, a quest with one objective counts its items, and "worth unknown" no longer fills a line.'] = "Ziele zeigen ihre Anzahl nur noch einmal, eine Quest mit nur einem Ziel zählt ihre Gegenstände, und 'Wert unbekannt' füllt keine Zeile mehr.",
  ["Bastian's minimap styles show only the herbs and ore your tracking finds, no more stray pins on you or on quest marks."] = "Bastians Minikarten-Stile zeigen nur noch die Kräuter und Erze, die dein Aufspüren findet, keine verirrten Pins mehr auf dir oder auf Questmarkierungen.",
  ["Quests now open on a parchment sheet with the task first, the story and large rewards, from My quests, the map and on hover at the Orbiter's quest marks."] = "Quests öffnen sich jetzt auf einem Pergamentblatt mit der Aufgabe zuerst, der Geschichte und großen Belohnungen: aus Meine Quests, von der Karte und beim Überfahren der Questmarkierungen des Orbiters.",
  ["Rewards come from the game itself, so quests no source knows show their real experience, money and items."] = "Belohnungen kommen aus dem Spiel selbst, sodass auch Quests, die keine Quelle kennt, ihre echte Erfahrung, ihr Geld und ihre Gegenstände zeigen.",
  ["My quests shows each quest on two lines, a finished quest has its own mark and says who takes it, and the voice and chain buttons stay on the row."] = "Meine Quests zeigt jede Quest auf zwei Zeilen, eine abgeschlossene Quest hat ein eigenes Zeichen und sagt, wer sie annimmt, und die Buttons für Stimme und Reihe bleiben in der Zeile.",
  ["The chain symbol shows a quest chain as a trail with every step, what it needs and what is still ahead."] = "Das Reihen-Symbol zeigt eine Questreihe als Pfad mit jedem Schritt, was er braucht und was noch vor dir liegt.",
  ["The map shows the targets of one quest, the focused or the nearest, and finished quests' hand-ins as large signs."] = "Die Karte zeigt die Ziele einer Quest, der fokussierten oder der nächsten, und die Abgabeorte abgeschlossener Quests als große Zeichen.",
  ["A second click on a quest closes its sheet, and the sheet shows the quest giver and the target in 3D."] = "Ein zweiter Klick auf eine Quest schließt ihr Blatt, und das Blatt zeigt den Questgeber und das Ziel in 3D.",
  ["Show on map opens at the nearest group of a quest's targets, not between two far camps."] = "Auf der Karte zeigen öffnet sich bei der nächsten Gruppe von Zielen einer Quest, nicht zwischen zwei weit entfernten Lagern.",
  ["Auctioneers, stable masters, innkeepers, bankers, flight masters and battlemasters are marked as what they are, and several hundred more vendors and repairers are found."] = "Auktionatoren, Stallmeister, Gastwirte, Bankiers, Flugmeister und Schlachtmeister sind als das markiert, was sie sind, und einige hundert weitere Händler und Reparierer werden gefunden.",
  ["A page in the Browser reads like the quest sheet: the figure large at the left on a wide window, the name and what matters first, the main buttons with the rest under More, and chapters in one column instead of a grid of blocks."] = "Eine Seite im Browser liest sich wie das Questblatt: das Bild groß links in einem breiten Fenster, der Name und das Wichtige zuerst, die Hauptbuttons mit dem Rest unter Mehr, und Kapitel in einer Spalte statt in einem Raster aus Blöcken.",
  ['Pages are sorted into chapters in a fixed reading order: a zone\'s quests under one heading, an item under "Where to get it", "What it is for", "Worth" and "Yours", a monster\'s drops first.'] = "Seiten sind in einer festen Lesereihenfolge in Kapitel gegliedert: die Quests einer Zone unter einer Überschrift, ein Gegenstand unter 'Wo man ihn bekommt', 'Wofür er gut ist', 'Wert' und 'Deins', bei einem Monster zuerst seine Beute.",
  ["A page in the Browser is drawn on parchment like the quest sheet, its rows are calm (two lines, icons only under the mouse), and a zone's quest groups you cannot act on yet are folded until clicked."] = "Eine Seite im Browser wird wie das Questblatt auf Pergament gezeichnet, ihre Zeilen sind ruhig (zwei Zeilen, Symbole nur unter der Maus), und Questgruppen einer Zone, auf die du noch nicht reagieren kannst, sind bis zum Klick eingeklappt.",
  ["A zone's page lists its people by what they do, vendors, trainers, zones and dungeons say in one sentence what they are, quests far above your level no longer lead \"To do here\", and pages on parchment keep the paper's colours under the mouse and switch without a reload."] = "Die Seite einer Zone listet ihre Bewohner nach dem, was sie tun, Händler, Lehrer, Zonen und Dungeons sagen in einem Satz, was sie sind, Quests weit über deiner Stufe führen nicht mehr 'Hier zu erledigen' an, und Seiten auf Pergament behalten unter der Maus die Farben des Papiers und wechseln ohne Neuladen.",
  ["Stormwind's bankers, guards, mailboxes and other people and objects inside the city are listed and shown in Stormwind City, no longer in Elwynn Forest."] = "Stormwinds Bankiers, Wachen, Briefkästen und andere Personen und Objekte in der Stadt werden aufgelistet und in Stormwind City gezeigt, nicht mehr in Elwynn Forest.",
  ["Test and placeholder records of the game's data (unused NPCs, invisible triggers, deprecated and test items, the weapons monsters hold) no longer show in lists, zone pages and the search."] = "Test- und Platzhalterdatensätze aus den Spieldaten (unbenutzte NPCs, unsichtbare Auslöser, veraltete und Testgegenstände, die Waffen, die Monster halten) erscheinen nicht mehr in Listen, Zonenseiten und der Suche.",
  ['"To do here" ranks a quest by the experience it really gives where the game data names it, no longer by an estimate from its level.'] = "'Hier zu erledigen' ordnet eine Quest nach der Erfahrung, die sie wirklich gibt, wo die Spieldaten sie nennen, nicht mehr nach einer Schätzung aus ihrer Stufe.",
  ["Pages on parchment keep readable colours everywhere, a place's mini map opens the large map there, a dungeon's floor map no longer sticks to other pages, the quest sheet opens on the free side of the Orbiter, and a locked Orbiter says that it is locked."] = "Seiten auf Pergament behalten überall lesbare Farben, die Minikarte eines Ortes öffnet dort die große Karte, die Etagenkarte eines Dungeons bleibt nicht mehr an anderen Seiten hängen, das Questblatt öffnet sich auf der freien Seite des Orbiters, und ein fixierter Orbiter sagt, dass er fixiert ist.",
  ["The Browser's navigation is a bar of category buttons on top, and the list always stands beside the page as two tiles; a narrow or docked window shows one of them at a time."] = "Die Navigation des Browsers ist eine Leiste mit Kategorie-Buttons oben, und die Liste steht immer als zwei Kacheln neben der Seite; ein schmales oder angedocktes Fenster zeigt jeweils nur eines von beiden.",
  ["The Browser's lists and search results are tiles: a picture, the name and a line that says what it is."] = "Die Listen und Suchergebnisse des Browsers sind Kacheln: ein Bild, der Name und eine Zeile, die sagt, was es ist.",
  ["Browser lists show each thing as a tile with its own facts: a quest's state, giver, level and chain step, a monster's level and rank, a zone's level band."] = "Listen im Browser zeigen jedes Ding als Kachel mit eigenen Angaben: bei einer Quest Zustand, Geber, Stufe und Reihenschritt, bei einem Monster Stufe und Rang, bei einer Zone das Stufenband.",
  ["The Orbiter has a small lock under its play button: click it to lock the ring in place or to move it freely."] = "Der Orbiter hat unter seinem Abspielbutton ein kleines Schloss: Klick darauf fixiert den Ring an seinem Platz oder macht ihn frei beweglich.",
  ["The Browser's Slim mode is gone; the quest tracker frame (/bq tracker) is the tracker, and a Browser left in slim mode opens wide again."] = "Der Slim-Modus des Browsers ist entfallen; der Questverfolgungs-Rahmen (/bq tracker) ist der Tracker, und ein Browser, der im Slim-Modus geblieben ist, öffnet sich wieder breit.",
  ["The Browser's filters stand beside the search box, and a chip inside the box says where the list and the search look: your zone, your continent or everywhere."] = "Die Filter des Browsers stehen neben dem Suchfeld, und ein Chip im Feld sagt, wo Liste und Suche suchen: deine Zone, dein Kontinent oder überall.",
  ["A page in the Browser shows its parts as cards: a zone's quests, people and monsters as tiles, four at a glance and the rest one click away, with nothing folded."] = "Eine Seite im Browser zeigt ihre Teile als Karten: die Quests, Bewohner und Monster einer Zone als Kacheln, vier auf einen Blick und der Rest einen Klick entfernt, ohne eingeklappte Teile.",
  ["A quest's page in the Browser is the same quest sheet as beside the Orbiter: the task first, the story, the rewards as tiles, with its people and its chain as cards below."] = "Die Seite einer Quest im Browser ist dasselbe Questblatt wie neben dem Orbiter: zuerst die Aufgabe, dann die Geschichte, die Belohnungen als Kacheln, darunter ihre Bewohner und ihre Reihe als Karten.",
  ["A zone, a person or a dungeon in the Browser can be stepped into: a click on the edge of its tile shows its quests, people and monsters in the list, one group open at a time, while the page shows what you pick."] = "In eine Zone, eine Person oder einen Dungeon im Browser kann man hineintreten: Ein Klick auf den Rand ihrer Kachel zeigt ihre Quests, Bewohner und Monster in der Liste, jeweils eine Gruppe offen, während die Seite zeigt, was du auswählst.",
  ["A quest chain is a page of its own: the Quest chains list opens the chain with its steps in order, how far you are, the next step and the zones it leads through."] = "Eine Questreihe ist eine eigene Seite: Die Liste Questreihen öffnet die Reihe mit ihren Schritten in Reihenfolge, wie weit du bist, dem nächsten Schritt und den Zonen, durch die sie führt.",
  ["A quest chain's page shows its way as coloured step tiles joined by arrows; the mouse on a step shows that quest's sheet and a click opens it."] = "Die Seite einer Questreihe zeigt ihren Weg als farbige Schrittkacheln, durch Pfeile verbunden; die Maus auf einem Schritt zeigt das Blatt dieser Quest, ein Klick öffnet es.",
  ["A quest in a chain shows its step, the chain and the steps before and after under its name; the chain button opens the chain's page instead of a window of its own."] = "Eine Quest in einer Reihe zeigt unter ihrem Namen ihren Schritt, die Reihe und die Schritte davor und danach; der Reihen-Button öffnet die Seite der Reihe statt eines eigenen Fensters.",
  ["A zone's page lists the quest chains that pass through it, and the chain list is grouped by how far you are, with filters for progress, kind and length."] = "Die Seite einer Zone listet die Questreihen, die durch sie führen, und die Reihenliste ist danach gruppiert, wie weit du bist, mit Filtern für Fortschritt, Art und Länge.",
  ["A chain's page shows its side quests under the step they follow, and the steps of other races and classes dashed."] = "Die Seite einer Reihe zeigt ihre Nebenquests unter dem Schritt, auf den sie folgen, und die Schritte anderer Völker und Klassen gestrichelt.",
  ["Follow on a quest chain's page tracks the step you are on and, after the hand-in, the next one by itself."] = "Folgen auf der Seite einer Questreihe verfolgt den Schritt, auf dem du bist, und nach der Abgabe von selbst den nächsten.",
  ["The Browser's lists are named People, Monsters, Gathering and Chains, and a list with nothing in it shows no button."] = "Die Listen des Browsers heißen Bewohner, Monster, Sammeln und Reihen, und eine leere Liste zeigt keinen Button.",
  ["The coloured words on parchment pages and on the quest sheet are darker, so they read against the paper; a few colours on list tiles are a touch brighter."] = "Die farbigen Wörter auf Pergamentseiten und auf dem Questblatt sind dunkler, sodass sie sich vom Papier abheben; einige Farben auf Listenkacheln sind etwas heller.",
  ["A double click on a tile in the Browser's list steps inside the thing, like the arrow at the tile's edge."] = "Ein Doppelklick auf eine Kachel in der Liste des Browsers tritt in die Sache hinein, wie der Pfeil am Rand der Kachel.",
  ["A thing's places show as a small map of each zone in your map style, with a dot for every place; a click opens the large map there."] = "Die Orte einer Sache erscheinen als kleine Karte jeder Zone in deinem Kartenstil, mit einem Punkt für jeden Ort; ein Klick öffnet dort die große Karte.",
  ["Zephras Isle no longer shows an empty map in the Blizzard, Modern, Pencil and Parchment styles."] = "Zephras Isle zeigt in den Stilen Blizzard, Modern, Pencil und Parchment keine leere Karte mehr.",
  ["The zones Forever added now have their people, objects, quest hand-ins, objectives and objective texts, and the airships to Zephras Isle are on the routes."] = "Die Zonen, die Forever hinzugefügt hat, haben jetzt ihre Bewohner, Objekte, Questabgaben, Ziele und Zieltexte, und die Luftschiffe nach Zephras Isle sind in den Routen.",
  ["A zone's tile shows the zone as a small map, and opening a part of a zone shows that part's people, monsters or quests as dots on the zone's map."] = "Die Kachel einer Zone zeigt die Zone als kleine Karte, und das Öffnen eines Teils einer Zone zeigt die Bewohner, Monster oder Quests dieses Teils als Punkte auf der Karte der Zone.",
  ["Forever's vendors show their stock, quests show the XP players measured and the rewards seen in Forever, and more Classic creatures have a place on the map."] = "Die Händler von Forever zeigen ihr Sortiment, Quests zeigen die von Spielern gemessene Erfahrung und die in Forever gesehenen Belohnungen, und mehr Classic-Kreaturen haben einen Platz auf der Karte.",
  ['The search no longer hangs on "Searching ..." while the quest texts are not loaded.'] = "Die Suche bleibt nicht mehr bei 'Suche ...' hängen, solange die Questtexte nicht geladen sind.",
  ["The Browser's lists open on everything instead of jumping to your zone, and most have a Zone filter."] = "Die Listen des Browsers öffnen sich auf Alles, statt zu deiner Zone zu springen, und die meisten haben einen Zonenfilter.",
  ["The Browser has Gold Stories and All Notes in its top row, farm spots link to their story in the book, and a setting chooses the style of the mini maps."] = "Der Browser hat Goldgeschichten und Alle Notizen in seiner oberen Reihe, Farmplätze verweisen auf ihre Geschichte im Buch, und eine Einstellung wählt den Stil der Minikarten.",
  ["Routes now lead to the doors of the City of Dalaran, the Excavation Site in the Wetlands, the Ruins of Lordaeron and the Hall of Thanes."] = "Routen führen jetzt zu den Türen der Stadt Dalaran, der Ausgrabungsstätte in den Wetlands, den Ruinen von Lordaeron und der Halle der Thane.",
  ["Every Forever market now shows its own auction prices where they exist, and says which market a price comes from."] = "Jeder Forever-Markt zeigt jetzt seine eigenen Auktionspreise, wo es sie gibt, und sagt, von welchem Markt ein Preis stammt.",
  ["The Browser's search groups its results by list and every category button says how many it found; mini maps show where you stand; a search typed inside a zone stays in that zone; item and recipe tiles say what they are; chains show on the map, route and list their rewards."] = "Die Suche des Browsers gruppiert ihre Ergebnisse nach Liste, und jeder Kategorie-Button sagt, wie viele er gefunden hat; Minikarten zeigen, wo du stehst; eine in einer Zone getippte Suche bleibt in dieser Zone; Gegenstands- und Rezeptkacheln sagen, was sie sind; Reihen erscheinen auf der Karte, auf der Route und in der Liste mit ihren Belohnungen.",
  ["Stormwind on the Blizzard map style is the same city zoomed out and zoomed in, and the sea in the map styles no longer shows flat patches around the coasts."] = "Stormwind im Blizzard-Kartenstil ist dieselbe Stadt herausgezoomt und hineingezoomt, und das Meer in den Kartenstilen zeigt um die Küsten keine flachen Flecken mehr.",
  ["Auction prices left over from the beta are now labelled as such."] = "Auktionspreise, die aus der Beta übrig geblieben sind, werden jetzt als solche gekennzeichnet.",
  ["Gold shows craft margins, disenchant value, whether a price is high or low in its range, a ledger of your sales and purchases, the market's best hours, and prices from AHledger, Auctionator or TSM when you have them."] = "Gold zeigt Herstellungsmargen, Entzauberungswert, ob ein Preis in seiner Spanne hoch oder niedrig ist, ein Hauptbuch deiner Verkäufe und Einkäufe, die besten Stunden des Marktes und Preise von AHledger, Auctionator oder TSM, wenn du sie hast.",
  ["Routes to Zephras Isle use Dalaran's skyboat, the skycutter at Skywatcher Plateau and, for the Alliance, the portal in Stormwind's Wizard's Sanctum."] = "Routen nach Zephras Isle nutzen Dalarans Himmelsboot, den Skycutter auf Skywatcher Plateau und, für die Allianz, das Portal im Zaubersanktum von Stormwind.",
  ["The gold stories no longer judge what they tell: the stamps, the verified and refuted labels and the status filter on farm spots are gone."] = "Die Goldgeschichten urteilen nicht mehr über das, was sie erzählen: die Stempel, die Etiketten verifiziert und widerlegt und der Statusfilter bei Farmplätzen sind weg.",
  ["Bastian's Gold Adventures opens on a painted map of the world with every story as a picture with its level; a click opens the story, and the book stays one tab away."] = "Bastian's Gold Adventures öffnet sich auf einer gemalten Weltkarte, jede Geschichte als Bild mit ihrer Stufe; ein Klick öffnet die Geschichte, und das Buch bleibt einen Tab entfernt.",
  ["Every gold story is open from the start."] = "Jede Goldgeschichte ist von Anfang an offen.",
  ["The Rumour mill is now a plain list of what travellers are saying this week, one line each with who said it and the video, one click from the map."] = "Die Gerüchteküche ist jetzt eine schlichte Liste dessen, was Reisende diese Woche erzählen, eine Zeile je Gerücht mit dem, der es gesagt hat, und dem Video, einen Klick von der Karte entfernt.",
  ["The stories' window is now called Bastian's Gold Adventures, and it has a new story: Wolf Flanks in Duskwood."] = "Das Fenster der Geschichten heißt jetzt Bastian's Gold Adventures und hat eine neue Geschichte: Wolf Flanks in Duskwood.",
  ["Quests: right-click a quest in your log to abandon it; the game asks first."] = "Quests: Rechtsklick auf eine Quest in deinem Log, um sie abzubrechen; das Spiel fragt zuerst.",
  ["Chat: the Up and Down keys recall your sent lines on Forever too (Alt+Up stays the game's)."] = "Chat: Die Tasten Pfeil hoch und runter rufen auch auf Forever deine gesendeten Zeilen zurück (Alt+Hoch bleibt dem Spiel).",
  ["Orbiter: hovering a quest mark shows the quest's chain position and its rewards (money, reputation, items)."] = "Orbiter: Beim Zeigen auf eine Questmarke erscheinen die Position in der Questreihe und die Belohnungen (Geld, Ruf, Gegenstände).",
  ["Quests: the zone view no longer errors on quests that are new in Forever."] = "Quests: Die Zonenansicht meldet keinen Fehler mehr bei Quests, die neu in Forever sind.",
  ["Core: no catalogue warning when a voice line starts or a quest reward loads."] = "Core: Keine Katalogwarnung mehr, wenn eine Sprachzeile startet oder eine Questbelohnung geladen wird.",
  ["Bastian's minimap shows the herbs, ore and creatures your tracking finds on its own styles too, and the game's tracking button is back in its tools row."] = "Bastians Minikarte zeigt die Kräuter, Erze und Kreaturen, die dein Aufspüren findet, nun auch in ihren eigenen Stilen, und der Aufspüren-Knopf des Spiels ist zurück in ihrer Werkzeugleiste.",
  ["The session plan (what fits into the next 30 to 180 minutes) moved from Route's Explore to Bastian's Gold and is off until you switch it on in Gold's settings."] = "Der Sitzungsplan (was in die nächsten 30 bis 180 Minuten passt) ist von Routes Erkunden zu Bastian's Gold gewandert und bleibt aus, bis du ihn in Golds Einstellungen einschaltest.",
  ["Other addons can ask Bastian's for any thing's name and places, your notes near a spot and your gold income through Bastians.API."] = "Andere Addons können Bastian's über Bastians.API nach Namen und Orten jeder Sache, deinen Notizen in der Nähe eines Punkts und deinem Goldeinkommen fragen.",
  ["When Bastian's Helpers restocks an item, it tells you if another vendor sells it cheaper and where."] = "Wenn Bastian's Helpers einen Gegenstand nachkauft, sagt es dir, ob ein anderer Händler ihn billiger verkauft und wo.",
  ["What's new speaks your language: German, French, Spanish, Korean and Chinese."] = "Was ist neu spricht deine Sprache: Deutsch, Französisch, Spanisch, Koreanisch und Chinesisch.",
  ["An item's price page shows a small chart of the prices your own auction house scans saw over the last two weeks."] = "Die Preisseite eines Gegenstands zeigt eine kleine Kurve der Preise, die deine eigenen Auktionshaus-Scans in den letzten zwei Wochen gesehen haben.",
  ["Mail rules: tell Helpers which character gets your herbs, ore, cloth and more, and one click beside the send tab fills the mail."] = "Postregeln: sag Helpers, welcher Charakter deine Kräuter, Erze, Stoffe und mehr bekommt; ein Klick neben dem Senden-Reiter füllt die Post.",
  ["Campfire can share your fire on a public channel and show everyone's fires (off by default, with a block list)."] = "Campfire kann dein Feuer in einem öffentlichen Kanal teilen und die Feuer aller zeigen (standardmäßig aus, mit einer Sperrliste).",
  ["Bastian's Suite now speaks Russian and Brazilian Portuguese."] = "Bastian's Suite spricht jetzt Russisch und brasilianisches Portugiesisch.",
  ["A Gestures command can now cast, use and target: /cast and friends run as a macro when you click the wedge."] = "Ein Gestures-Befehl kann jetzt zaubern, benutzen und anvisieren: /cast und Co. laufen als Makro, wenn du den Keil anklickst.",
  ["Other addons can now read and set Bastian's waypoint, read the account's gold and the suite's item sets through Bastians.API."] = "Andere Addons können über Bastians.API jetzt Bastian's Wegpunkt lesen und setzen sowie das Gold des Accounts und die Gegenstandsgruppen der Suite lesen.",
  ["Spoken 3.8.0, the launch client's copy, is now the version the suite was tested with; the hub no longer flags it as newer."] = "Spoken 3.8.0, die Version des Launch-Clients, gilt jetzt als getestet; der Hub meldet sie nicht mehr als neuer.",
  ["The game's voice that reads quest texts is a woman's by default and can be chosen in the Orbiter's settings."] = "Die Stimme des Spiels, die Questtexte vorliest, ist standardmäßig eine Frauenstimme und lässt sich in den Einstellungen des Orbiters wählen.",
  ["Without Spoken, the Orbiter reads a quest's text with the game's own voice (Accessibility settings)."] = "Ohne Spoken liest der Orbiter den Text einer Quest mit der Stimme des Spiels vor (Einstellungen für Barrierefreiheit).",
  ["Bastian's Orbiter (the Voice addon, renamed): the panel keeps its place and grows around its middle, says what it plays and what a click did, has pictogram controls and its own minimap button; the game's settings pages of the suite scroll."] = "Bastian's Orbiter (das umbenannte Voice-Addon): Das Panel behält seinen Platz und wächst um seine Mitte, sagt, was es abspielt und was ein Klick bewirkt hat, hat Piktogramm-Bedienelemente und einen eigenen Minimap-Button; die Einstellungsseiten der Suite im Spiel lassen sich scrollen.",
  ["Bastian's Voice: Play on quests, zones, areas, bosses and books where Spoken has a line, the Lore Orbit around you, and quest conversations without the game's windows (off by default)."] = "Bastian's Voice: Abspielen bei Quests, Zonen, Gebieten, Bossen und Büchern, wo Spoken eine Zeile hat, der Geschichtenkreis um dich herum und Questgespräche ohne die Fenster des Spiels (standardmäßig aus).",
  ["A note you add on a dungeon's page (or any other page) now shows on that page."] = "Eine Notiz, die du auf der Seite eines Dungeons (oder einer anderen Seite) hinzufügst, erscheint jetzt auf dieser Seite.",
  ["The minimap's search finds only NPCs, quests, zones, your notes and bookmarks, and marks the place it jumps to; a quest marks its quest giver."] = "Die Suche der Minimap findet nur NPCs, Quests, Zonen, deine Notizen und Lesezeichen und markiert den Ort, zu dem sie springt; eine Quest markiert ihren Questgeber.",
  ['"Show on map" now draws what you chose (its icon and name at every place) and selects it, even when its layer is off.'] = '"Auf der Karte zeigen" zeichnet jetzt, was du gewählt hast (sein Symbol und seinen Namen an jedem Ort), und wählt es aus, auch wenn seine Ebene ausgeschaltet ist.',
  ["The map has a Dungeons and raids layer, and it switches on by itself when you pick a dungeon in the Browser."] = 'Die Karte hat eine Ebene "Dungeons und Raids", die sich von selbst einschaltet, wenn du im Browser einen Dungeon wählst.',
  ["New app Bastian's Helpers: sells junk, repairs, restocks, takes all mail, helps at quest givers and shows IDs on tooltips."] = "Neue App Bastian's Helpers: verkauft Plunder, repariert, kauft Vorräte nach, nimmt alle Post, hilft bei Questgebern und zeigt IDs in Tooltips.",
  ["The dungeon pages name the right bosses; some showed an unrelated creature (Shadowfang Keep's first boss as Archaedas) with loot that was not its own."] = "Die Dungeon-Seiten nennen die richtigen Bosse; einige zeigten eine fremde Kreatur (der erste Boss der Burg Schattenfang als Archaedas) mit Beute, die nicht seine eigene war.",
  ["Minimap buttons close what they opened; Gestures' button opens its options; a switched-off app's button leads to its switch; a new button shows the welcome again."] = "Minimap-Buttons schließen, was sie geöffnet haben; der Button der Gesten öffnet deren Optionen; der Button einer ausgeschalteten App führt zu ihrem Schalter; ein neuer Button zeigt die Begrüßung erneut.",
  ["Forever's own dungeons (Dalaran, the Wetlands excavation, the Hall of Thanes, the Ruins of Lordaeron) now show Santiago Reyes' hand-drawn maps with the bosses marked - thank you, Santiago!"] = "Forevers eigene Dungeons (Dalaran, die Ausgrabung in den Sumpflanden, die Halle der Thane, die Ruinen von Lordaeron) zeigen jetzt die handgezeichneten Karten von Santiago Reyes mit markierten Bossen - danke, Santiago!",
  ["German, French and Spanish players read most quests' whole texts in their language, and the AddOn list speaks every language of the suite."] = "Deutsche, französische und spanische Spieler lesen die vollständigen Texte der meisten Quests in ihrer Sprache, und die AddOn-Liste spricht jede Sprache der Suite.",
  ["The game's AddOn list shows the suite as one folding \"Bastian's Suite\" header with the data packs and map styles folded under their app, in Korean and Chinese too."] = 'Die AddOn-Liste des Spiels zeigt die Suite als eine einklappbare Kopfzeile "Bastian\'s Suite", mit den Datenpaketen und Kartenstilen unter ihrer App eingeklappt, auch auf Koreanisch und Chinesisch.',
  ["Korean and Chinese players read the quests' whole texts in their language, and Bastian's Chat speaks French, Spanish, Korean and Chinese."] = "Koreanische und chinesische Spieler lesen die vollständigen Questtexte in ihrer Sprache, und Bastian's Chat spricht Französisch, Spanisch, Koreanisch und Chinesisch.",
  ["With Total RP 3 or MyRolePlay, Chat, Gestures and the Orbiter show other players' roleplay names."] = "Mit Total RP 3 oder MyRolePlay zeigen Chat, Gestures und der Orbiter die Rollenspielnamen anderer Spieler an.",
  ["A new welcome: choose the Wanderer or the Scholar with a picture of your own race, set up your pack, and try your first five minutes step by step."] = "Ein neuer Willkommensbildschirm: Wähle den Wanderer oder den Gelehrten mit einem Bild deines eigenen Volkes, richte dein Paket ein und probiere deine ersten fünf Minuten Schritt für Schritt aus.",
  ["Bastian's Campfire: a card while a fire is near, a camp ring in Gestures, share the fire with your group and guild, and a planner of every camp feature."] = "Bastian's Campfire: eine Karte, solange ein Feuer in der Nähe ist, ein Lagerring in den Gesten, das Feuer mit Gruppe und Gilde teilen und eine Übersicht aller Lagerfunktionen.",
  ["Emotes in Bastian's Chat now show in the colour scheme's own emote colour, for roleplay."] = "Emotes in Bastian's Chat erscheinen jetzt in der eigenen Emote-Farbe des Farbschemas, fürs Rollenspiel.",
  ["A Gestures wedge can run one of your own macros with a click, and runs the game's own commands such as /reload; Quests' item buttons work with \"cast on key down\"."] = 'Ein Gesten-Keil kann per Klick eines deiner eigenen Makros ausführen und führt die Befehle des Spiels aus, etwa /reload; die Gegenstands-Buttons von Quests funktionieren mit "Bei Tastendruck zaubern".',
  ["The Korean and Chinese texts of the suite read naturally and use the game's own terms."] = "Die koreanischen und chinesischen Texte der Suite lesen sich natürlich und verwenden die Begriffe des Spiels.",
  ["Build your Gestures rings as you like: name them, pick any emote, your own lines, commands, the suite's and the game's controls through one filter; the wheel turns the right way; a conversation's choices no longer overlap on the Orbiter."] = "Baue deine Gesten-Ringe nach Belieben: benenne sie, wähle beliebige Emotes, eigene Zeilen, Befehle sowie die Bedienelemente der Suite und des Spiels über einen einzigen Filter; das Rad dreht sich in die richtige Richtung; die Auswahlmöglichkeiten eines Gesprächs überlappen sich am Orbiter nicht mehr.",
  ["When someone challenges, trades or invites you, Gestures offers a bow, a wave or a polite decline; Chat's + menu has a Roleplay tab."] = "Wenn dich jemand herausfordert, mit dir handelt oder dich einlädt, bieten die Gesten eine Verbeugung, ein Winken oder eine höfliche Absage an; das +-Menü des Chats hat einen Rollenspiel-Tab.",
  ["Gestures' Route home, Mark heard and Toggle the tracker wedges light up."] = 'Die Keile "Route nach Hause", "Als gehört markieren" und "Tracker ein/aus" der Gesten leuchten jetzt auf.',
  ["The Orbiter says when your Spoken is newer or older than the suite was tested with, never talks over Spoken or Spoken Players, and Bastian's Helpers, Chat and the Orbiter show up on broker displays; other addons can ask who knows a recipe, let the Orbiter speak, read your play preset and open any app."] = "Der Orbiter meldet, wenn dein Spoken neuer oder älter ist als die Version, mit der die Suite getestet wurde, redet nie über Spoken oder Spoken Players hinweg, und Bastian's Helpers, Chat und der Orbiter erscheinen auf Broker-Anzeigen; andere Addons können fragen, wer ein Rezept kennt, den Orbiter sprechen lassen, dein Spielprofil lesen und jede App öffnen.",
  ["Every app wears its own mark on the minimap, in the hub, on broker displays and in the AddOns list: a compass star for the suite, a scroll for Quests, a pin for the Map, a lens for the Browser, a balance for Gold, a signpost for Route, a quill for Notes, two characters for Alts, a wrench for Helpers, bubbles for Chat, a hand for Gestures."] = "Jede App trägt ihr eigenes Zeichen an der Minimap, im Hub, auf Broker-Anzeigen und in der AddOn-Liste: ein Kompassstern für die Suite, eine Schriftrolle für Quests, eine Markierung für die Karte, eine Lupe für den Browser, eine Waage für Gold, ein Wegweiser für Route, eine Feder für Notizen, zwei Figuren für Alts, ein Schraubenschlüssel für Helpers, Sprechblasen für Chat, eine Hand für Gestures.",
  ["Choose how you play at the first start: the Wanderer hears Azeroth with nearly no UI, the Scholar has every quest, creature, item and place one click away; Bastian's Gestures brings emote rings and courtesy; the hub explains every app and key."] = "Wähle beim ersten Start, wie du spielst: Der Wanderer hört Azeroth fast ohne Oberfläche, der Gelehrte hat jede Quest, Kreatur, jeden Gegenstand und Ort einen Klick entfernt; Bastian's Gestures bringt Emote-Ringe und Höflichkeit; der Hub erklärt jede App und jede Taste.",
  ["Every button shows its pictogram again and the words sit where they belong; chat tabs and buttons are easy to tell apart; the Orbiter's controls click with a creature shown, its hub drags it, and its answers are symbols; an item's page says which of your characters has it."] = "Jeder Button zeigt wieder sein Piktogramm und die Wörter sitzen, wo sie hingehören; Chat-Tabs und Buttons lassen sich leicht unterscheiden; die Bedienelemente des Orbiters klicken, solange eine Kreatur zu sehen ist, sein Hub zieht ihn, und seine Antworten sind Symbole; auf der Seite eines Gegenstands steht, welcher deiner Charaktere ihn hat.",
  ["Trainers say what they train on the map and on their page, and their list of spells shows who of your characters knows each one; item lists filter by who owns an item; the Orbiter hides with the clear-screen key and drags by its hub; the Browser's hover preview is a setting."] = "Lehrer sagen auf der Karte und auf ihrer Seite, was sie lehren, und ihre Zauberliste zeigt, wer von deinen Charakteren jeden einzelnen kennt; Gegenstandslisten lassen sich danach filtern, wem ein Gegenstand gehört; der Orbiter verschwindet mit der Taste zum Leeren des Bildschirms und lässt sich an seinem Hub ziehen; die Hover-Vorschau des Browsers ist eine Einstellung.",
  ["Every app offers a data-broker feed (Titan, Bazooka, ElvUI and the like), the Addon Compartment lists the suite, bag addons get the suite's item sets, and other addons can read the suite through Bastians.API."] = "Jede App bietet einen Data-Broker-Feed (Titan, Bazooka, ElvUI und dergleichen), das Addon-Fach listet die Suite auf, Taschen-Addons bekommen die Gegenstandssets der Suite, und andere Addons können die Suite über Bastians.API lesen.",
  ["The Orbiter's bubbles glide to their places and the one that plays is coloured; Show on map always draws what you chose; the junk filter also cleans the lines already on screen; the game's voice is found once the client lists it."] = 'Die Blasen des Orbiters gleiten an ihre Plätze, und die gerade abgespielte ist eingefärbt; "Auf der Karte zeigen" zeichnet immer, was du gewählt hast; der Plunderfilter säubert auch die Zeilen, die schon auf dem Bildschirm stehen; die Stimme des Spiels wird gefunden, sobald der Client sie auflistet.',
  ["Seven looks to pick from, including Night, Glass and Parchment; every button of the suite shows a pictogram; every colour scheme is checked for readable text."] = "Sieben Looks zur Auswahl, darunter Nacht, Glas und Pergament; jeder Button der Suite zeigt ein Piktogramm; jedes Farbschema ist auf lesbaren Text geprüft.",
  ["the Browser's filter pills use the pane's width and the first row is never hidden, the Mobs search works again, zones appear once, a preview needs Shift, and a note saved on a page shows at once."] = "Die Filter-Pillen des Browsers nutzen die Breite des Bereichs und die erste Zeile wird nie verdeckt, die Mobs-Suche funktioniert wieder, Zonen erscheinen nur einmal, eine Vorschau braucht Shift, und eine auf einer Seite gespeicherte Notiz erscheint sofort.",
  ['one search syntax in every box (words, "phrases", OR, -not, field:value, level>30), the text keys Ctrl+Backspace/Delete/Left/Right, a key that clears the screen for role play, a lock on every window, and the new look engine behind Modern and WoW.'] = 'Eine Suchsyntax in jedem Suchfeld (Wörter, "Phrasen", OR, -not, field:value, level>30), die Texttasten Ctrl+Backspace/Delete/Left/Right, eine Taste, die den Bildschirm für Rollenspiel leert, eine Sperre für jedes Fenster und die neue Look-Engine hinter Modern und WoW.',
  ['Bastian\'s Helpers also writes its notices into a chat tab named "Addons" when you have one.'] = 'Bastian\'s Helpers schreibt seine Meldungen auch in einen Chat-Tab namens "Addons", wenn du einen hast.',
  ['The colour picker opens in front of the settings, and no "blocked" message appears in combat.'] = "Der Farbwähler öffnet sich vor den Einstellungen, und im Kampf erscheint keine Meldung über Blockierung mehr.",
  ["The map's layer bar names each icon the moment you point at it."] = "Die Ebenenleiste der Karte nennt jedes Symbol, sobald du darauf zeigst.",
  ["Other addons can ask Bastian's for prices, quest state, the active route and travel times, start a route, and listen to its events through Bastians.API."] = "Andere Addons können Bastian's nach Preisen, Questständen, der aktiven Route und Reisezeiten fragen, eine Route starten und über Bastians.API auf ihre Ereignisse hören.",
  ["Wide buttons in the WoW look keep the game's rounded ends instead of stretching them."] = "Breite Buttons im WoW-Look behalten die runden Enden des Spiels, statt sie zu dehnen.",
  ["Bastian's apps show in Titan Panel, Bazooka, EllesmereUI's data bars and every other LibDataBroker display, in the addon compartment, and sort your bags in BetterBags, Baganator and AdiBags."] = "Bastian's Apps erscheinen in Titan Panel, Bazooka, den Datenleisten von EllesmereUI und jeder anderen LibDataBroker-Anzeige sowie im Addon-Fach, und sortieren deine Taschen in BetterBags, Baganator und AdiBags.",
  ["Bastian's Chat gets a live tab filter, tab windows that dock back, a Messenger of the WhatsApp kind with class icons and a search, and a lock on every chat window."] = "Bastian's Chat bekommt einen Live-Filter für Tabs, Tab-Fenster, die wieder andocken, einen Messenger im Stil von WhatsApp mit Klassensymbolen und einer Suche sowie eine Sperre für jedes Chatfenster.",
  ["All %d"] = "Alle %d",
  ["Step inside"] = "Hineingehen",
  -- UI/Dossier.lua: tabs inside a sheet, facts as tiles (ADR 0058, 07.11.2026)
  ["Overview"] = "Übersicht",
  ["unknown"] = "unbekannt",
})
